using System.Runtime.InteropServices;namespace MeshDriveSync;internal static class CredentialManager{const uint Generic=1,Persist=2;[StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Cred{public uint Flags,Type;public string Target,Comment;public System.Runtime.InteropServices.ComTypes.FILETIME Written;public uint BlobSize;public IntPtr Blob;public uint Persistence,AttrCount;public IntPtr Attr;public string Alias,User;}[DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CredWrite(ref Cred c,uint f);[DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CredRead(string t,uint type,uint f,out IntPtr p);[DllImport("advapi32.dll")]static extern void CredFree(IntPtr p);public static void Save(string target,string user,string password){var b=System.Text.Encoding.Unicode.GetBytes(password);var p=Marshal.AllocCoTaskMem(b.Length);try{Marshal.Copy(b,0,p,b.Length);var c=new Cred{Type=Generic,Target=target,User=user,Blob=p,BlobSize=(uint)b.Length,Persistence=Persist};if(!CredWrite(ref c,0))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}finally{for(int i=0;i<b.Length;i++)Marshal.WriteByte(p,i,0);Marshal.FreeCoTaskMem(p);}}public static(string User,string Password)?Read(string target){if(!CredRead(target,Generic,0,out var p))return null;try{var c=Marshal.PtrToStructure<Cred>(p);return(c.User,Marshal.PtrToStringUni(c.Blob,(int)c.BlobSize/2)??"");}finally{CredFree(p);}}}
